// Agrupa todos os cards retornados do Trello em um único item para que o próximo nó rode apenas 1 vez
return [{
  json: {
    cards: $input.all().map(item => item.json)
  }
}];

// Agrupa os contatos retornados da Evolution API em um único item para que o próximo nó rode apenas 1 vez
return [{
  json: {
    contacts: $input.all().map(item => item.json)
  }
}];

// ═══════════════════════════════════════════════════════
// Filtra contatos de conversas dos últimos 2 meses que não existem no Trello
// ═══════════════════════════════════════════════════════

const twoMonthsAgo = new Date();
twoMonthsAgo.setMonth(twoMonthsAgo.getMonth() - 2);

const chatsItems = $input.all();
const contactsData = $("Agrupar Contatos Evolution").first().json.contacts || [];
const cardsData = $("Agrupar Cards Trello").first().json.cards || [];

// Mapeia pushNames dos contatos pelo número de telefone
const contactsMap = {};
for (const contact of contactsData) {
  const rawJid = contact.remoteJid || '';
  if (!rawJid || contact.isGroup) continue;
  const phone = rawJid.split('@')[0];
  const name = (contact.pushName || '').trim();
  if (name) {
    contactsMap[phone] = name;
  }
}

// Mapeia cards do Trello para checar duplicação
const existingCards = cardsData.map(card => ({
  name: (card.name || '').toLowerCase(),
  desc: (card.desc || '').toLowerCase()
}));

const newLeads = [];

for (const chat of chatsItems) {
  const updatedAtStr = chat.json.updatedAt;
  if (!updatedAtStr) continue;

  const updatedAtDate = new Date(updatedAtStr);
  if (updatedAtDate < twoMonthsAgo) continue; // Pula conversas com mais de 2 meses

  const rawJid = chat.json.remoteJid || '';
  if (rawJid.endsWith('@g.us')) continue; // Ignora grupos

  let phone = '';
  if (rawJid.includes('@s.whatsapp.net') || rawJid.includes('@c.us')) {
    phone = rawJid.split('@')[0];
  } else {
    const altJid = chat.json.lastMessage?.key?.remoteJidAlt || '';
    if (altJid.includes('@s.whatsapp.net') || altJid.includes('@c.us')) {
      phone = altJid.split('@')[0];
    }
  }

  if (!phone) continue;

  const alreadyExists = existingCards.some(card => 
    card.name.includes(phone) || card.desc.includes(phone)
  );

  if (!alreadyExists) {
    const displayName = contactsMap[phone] || chat.json.pushName || 'Desconhecido';
    const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

    newLeads.push({
      json: {
        phone,
        pushName: displayName,
        cardTitle: displayName !== 'Desconhecido' ? `${displayName} (${phone})` : `Lead ${phone}`,
        cardDescription: 
          `📲 Lead importador historicamente via WhatsApp (Últimos 2 meses)\n` +
          `Fonte: Evolution API (Histórico)\n\n` +
          `Nome: ${displayName}\n` +
          `Número: ${phone}\n` +
          `Última Conversa: ${new Date(updatedAtStr).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}\n` +
          `Importado em: ${now}`
      }
    });
  }
}

return newLeads;
